import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// Font Loader Hook (System Requirement)
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Schema Definition ---



export type StackedBarChartProps = Record<string, any>;

const StackedBarChart: React.FC<StackedBarChartProps> = ({
  backgroundColor = "#1034a6", // Deep Blue from image
  transparentBackground = false,
  durationInSeconds = 8,
  
  series1Color = "#b3ef4d", // Lime Green
  series2Color = "#ffffff", // White
  series3Color = "#f5a638", // Orange
  
  series1Label = "Series 1",
  series2Label = "Series 2",
  series3Label = "Series 3",
  
  // Defaults based on the visual analysis of the image
  series1Data = [8, 12, 16, 20],
  series2Data = [8, 10, 10, 24],
  series3Data = [4, 8, 10, 6],
  xLabels = ["Item 1", "Item 2", "Item 3", "Item 4"],
  
  title = "Summary",
  description = "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Quisque suscipit magna ut est posuere pellentesque. Maecenas ac lectus venenatis, dignissim erat ut, convallis sem.",
  titleColor = "#ffffff",
  bodyColor = "#e0e0e0",
}) => {
  // Load Fonts
  useFontLoader(["Inter", "Playfair Display"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Calculations & Logic ---

  // Handle transparency
  const bg = transparentBackground ? "transparent" : backgroundColor;

  // Determine Max Y Value for scaling
  // Calculate total height for each stack to find the max
  const stackTotals = xLabels.map((_, i) => {
    const v1 = series1Data[i] || 0;
    const v2 = series2Data[i] || 0;
    const v3 = series3Data[i] || 0;
    return v1 + v2 + v3;
  });
  
  const maxStackHeight = Math.max(...stackTotals, 50); // Minimum 50 to match image scale
  // Round up to nearest 10 for nice axis
  const yAxisMax = Math.ceil(maxStackHeight / 10) * 10;
  
  // Layout Constants
  const chartHeight = height * 0.50; // Slightly reduced to fit vertically centered layout
  const chartWidth = width * 0.7;
  const leftMargin = width * 0.15;
  const barWidthRatio = 0.6; // Width of bar relative to column width

  // --- Animations ---

  // Fade in for text
  const textOpacity = interpolate(frame, [30, 60], [0, 1], {
    extrapolateRight: "clamp",
  });
  const textSlide = interpolate(frame, [30, 60], [20, 0], {
    extrapolateRight: "clamp",
    easing: (t) => t * (2 - t), // easeOutQuad-ish
  });

  // Grid lines reveal
  const gridWidthProgress = interpolate(frame, [0, 40], [0, 100], {
    extrapolateRight: "clamp",
    easing: (t) => Math.pow(t, 0.5), // easeOut
  });

  // --- Render Helpers ---

  // Y-Axis Grid Lines
  const gridLines = [];
  const steps = 5; // 0 to 50 usually has 5 steps of 10
  for (let i = 0; i <= steps; i++) {
    const value = Math.round((yAxisMax / steps) * i);
    
    gridLines.push(
      <div
        key={`grid-${i}`}
        style={{
          position: "absolute",
          left: 0,
          bottom: (value / yAxisMax) * chartHeight,
          width: "100%",
          height: 1,
          pointerEvents: "none",
        }}
      >
        {/* Horizontal Line */}
        <div
          style={{
            width: `${gridWidthProgress}%`,
            height: 1,
            backgroundColor: "rgba(255, 255, 255, 0.2)",
            transition: "none",
          }}
        />
        {/* Y-Axis Label */}
        <div
          style={{
            position: "absolute",
            left: -40,
            top: -10,
            width: 30,
            textAlign: "right",
            fontFamily: "Inter",
            fontSize: 24,
            color: "rgba(255, 255, 255, 0.7)",
            opacity: interpolate(frame, [10 + i * 5, 30 + i * 5], [0, 1], { extrapolateRight: "clamp" }),
          }}
        >
          {value}
        </div>
      </div>
    );
  }

  // Bars
  const bars = xLabels.map((label, i) => {
    const v1 = series1Data[i] || 0;
    const v2 = series2Data[i] || 0;
    const v3 = series3Data[i] || 0;
    
    // Calculate heights as percentages of the MAX chart height
    const h1 = (v1 / yAxisMax) * 100;
    const h2 = (v2 / yAxisMax) * 100;
    const h3 = (v3 / yAxisMax) * 100;

    // Staggered entrance per bar
    const barProgress = spring({
      frame: frame - 10 - (i * 5),
      fps,
      config: { damping: 15, stiffness: 120 },
    });

    return (
      <div
        key={`col-${i}`}
        style={{
          flex: 1,
          height: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "flex-end",
          position: "relative",
        }}
      >
        {/* The Bar Stack */}
        <div
          style={{
            width: `${barWidthRatio * 100}%`,
            height: "100%", // Contains the stack, but we only fill part of it
            display: "flex",
            flexDirection: "column-reverse", // Stack from bottom
            transform: `scaleY(${barProgress})`,
            transformOrigin: "bottom",
          }}
        >
          {/* Series 1 (Bottom) */}
          <div style={{ width: "100%", height: `${h1}%`, backgroundColor: series1Color }} />
          {/* Series 2 (Middle) */}
          <div style={{ width: "100%", height: `${h2}%`, backgroundColor: series2Color }} />
          {/* Series 3 (Top) */}
          <div style={{ width: "100%", height: `${h3}%`, backgroundColor: series3Color }} />
        </div>

        {/* X-Axis Label */}
        <div
          style={{
            position: "absolute",
            bottom: -40,
            width: "100%",
            textAlign: "center",
            fontFamily: "Inter",
            fontSize: 24,
            color: "white",
            opacity: interpolate(frame, [20 + i * 5, 40 + i * 5], [0, 1], { extrapolateRight: "clamp" }),
          }}
        >
          {label}
        </div>
      </div>
    );
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bg }}>
      
      {/* Subtle Grid Decoration (Top Left) */}
      <div style={{ position: "absolute", top: 0, left: 0, width: width * 0.3, height: height * 0.3, opacity: 0.1 }}>
         <svg width="100%" height="100%">
            <defs>
                <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
                    <path d="M 40 0 L 0 0 0 40" fill="none" stroke="white" strokeWidth="2"/>
                </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#grid)" />
         </svg>
      </div>

      {/* Main Content Container - Vertically Centered */}
      <AbsoluteFill style={{ 
          paddingLeft: leftMargin, 
          paddingRight: width * 0.05, 
          display: "flex", 
          flexDirection: "column", 
          justifyContent: "center"
      }}>
        
        {/* Chart Area */}
        <div style={{ 
            width: chartWidth, 
            height: chartHeight, 
            position: "relative",
            marginLeft: 50, // Offset for Y labels
            marginBottom: 60 // Margin for X-Axis labels
        }}>
            {/* Grid Lines Layer */}
            {gridLines}

            {/* Bars Layer */}
            <div style={{
                position: "absolute",
                top: 0,
                left: 0,
                width: "100%",
                height: "100%",
                display: "flex",
                flexDirection: "row",
                alignItems: "flex-end",
            }}>
                {bars}
            </div>
        </div>

        {/* Legend - Moved Below Graph */}
        <div style={{ 
            display: "flex", 
            justifyContent: "flex-start", 
            gap: 40, 
            marginLeft: 50, // Aligned with chart body
            marginBottom: 30, // Spacing before text
            opacity: interpolate(frame, [0, 30], [0, 1], { extrapolateRight: "clamp" })
        }}>
           {[
               { label: series1Label, color: series1Color },
               { label: series2Label, color: series2Color },
               { label: series3Label, color: series3Color },
           ].map((s, i) => (
             <div key={i} style={{ display: "flex", alignItems: "center", gap: 10 }}>
               <div style={{ width: 20, height: 20, backgroundColor: s.color }} />
               <span style={{ fontFamily: "Inter", fontSize: 20, color: "white" }}>{s.label}</span>
             </div>
           ))}
        </div>

        {/* Summary Text Area */}
        <div style={{
            marginLeft: 50,
            maxWidth: chartWidth,
            opacity: textOpacity,
            transform: `translateY(${textSlide}px)`
        }}>
            <h1 style={{
                fontFamily: "Playfair Display",
                fontSize: 60,
                fontWeight: 700,
                margin: "0 0 20px 0",
                color: titleColor,
            }}>
                {title}
            </h1>
            <p style={{
                fontFamily: "Inter",
                fontSize: 28,
                lineHeight: 1.5,
                color: bodyColor,
                margin: 0,
                maxWidth: "90%"
            }}>
                {description}
            </p>
        </div>

      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default StackedBarChart;